-- PawSpace UAT DEMO SEED (generated by scripts/uat-demo-seed-gen.mjs — do not hand-edit).
-- Puts real, derivable demo data behind every module UI so no staging page opens empty.
-- Every CREATE TABLE below is copied verbatim from the source file that owns it.
-- All rows carry a UATD marker and are inserted with INSERT OR IGNORE: safe to re-run,
-- and it never collides with staging-seed.sql or employee-seed.sql.
--
-- The AI rows were written by the REAL AI engine (scripts/ai-demo-run.mjs runs the same libs the
-- product runs), which is why their IDs carry the engine's own prefixes. The AI replies come from
-- a declared scripted provider recorded as provider='uat_demo_scripted' on every turn — no row
-- here is output from a live model. The rollout stage is seeded to 'staff_only': the assistant
-- answers the internal team, customers still reach a human until someone widens it on
-- /team/ai/rollout.
-- Demo 'today' is 2026-08-13.

CREATE TABLE IF NOT EXISTS ai_assistant_profile_versions (id TEXT PRIMARY KEY,profile_key TEXT NOT NULL,version INTEGER NOT NULL,status TEXT NOT NULL,brand_voice TEXT NOT NULL,supported_languages_json TEXT NOT NULL,greeting_text TEXT NOT NULL,fallback_text TEXT NOT NULL,provider_ref TEXT,model_ref TEXT,effective_from INTEGER,effective_to INTEGER,immutable_hash TEXT NOT NULL,created_by TEXT NOT NULL,reviewed_by TEXT,reviewed_at INTEGER,approved_by TEXT,approved_at INTEGER,activated_by TEXT,activated_at INTEGER,retired_at INTEGER,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,UNIQUE(profile_key,version));
CREATE TABLE IF NOT EXISTS ai_audience_rollout (id INTEGER PRIMARY KEY CHECK(id=1),stage TEXT NOT NULL DEFAULT 'off',reason TEXT,updated_by TEXT NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS ai_audit_events (id TEXT PRIMARY KEY,context_id TEXT,suggestion_id TEXT,action TEXT NOT NULL,actor_email TEXT NOT NULL,detail_json TEXT NOT NULL DEFAULT '{}',created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS ai_config_audit_events (id TEXT PRIMARY KEY,actor_email TEXT NOT NULL,action TEXT NOT NULL,entity_type TEXT NOT NULL,entity_id TEXT,detail_json TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS ai_context_snapshots (id TEXT PRIMARY KEY,actor_email TEXT NOT NULL,customer_id TEXT,booking_id TEXT,ticket_id TEXT,authorized_scope_json TEXT NOT NULL,context_json TEXT NOT NULL,pii_policy TEXT NOT NULL DEFAULT 'minimum_necessary',created_at INTEGER NOT NULL,expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS ai_conversation_sessions (id TEXT PRIMARY KEY,thread_id TEXT NOT NULL UNIQUE,customer_id TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'ai_active',provider TEXT NOT NULL DEFAULT 'not_connected',model_ref TEXT,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS ai_conversation_turns (id TEXT PRIMARY KEY,session_id TEXT NOT NULL,thread_id TEXT NOT NULL,customer_id TEXT NOT NULL,input_message_id TEXT NOT NULL,idempotency_key TEXT NOT NULL UNIQUE,channel TEXT NOT NULL,intent_code TEXT NOT NULL,intent_confidence REAL NOT NULL,context_id TEXT NOT NULL,provider TEXT NOT NULL,model_ref TEXT,output_text TEXT NOT NULL,latency_ms INTEGER NOT NULL DEFAULT 0,input_tokens INTEGER,output_tokens INTEGER,cost_minor INTEGER,policy_decision TEXT NOT NULL,outcome TEXT NOT NULL,handoff_reason TEXT,created_at INTEGER NOT NULL,completed_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS ai_evaluation_results (id TEXT PRIMARY KEY,suite_version TEXT NOT NULL,case_code TEXT NOT NULL,category TEXT NOT NULL,status TEXT NOT NULL,detail_json TEXT NOT NULL DEFAULT '{}',created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS ai_explicit_csat (id TEXT PRIMARY KEY,thread_id TEXT NOT NULL,customer_id TEXT NOT NULL,rating INTEGER NOT NULL,source TEXT NOT NULL,created_at INTEGER NOT NULL CHECK(rating BETWEEN 1 AND 5));
CREATE TABLE IF NOT EXISTS ai_handoff_events (id TEXT PRIMARY KEY,handoff_id TEXT NOT NULL,event_type TEXT NOT NULL,actor_email TEXT NOT NULL,detail_json TEXT NOT NULL DEFAULT '{}',created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS ai_handoffs (id TEXT PRIMARY KEY,thread_id TEXT NOT NULL,customer_id TEXT NOT NULL,session_id TEXT,reason TEXT NOT NULL,confidence REAL,queue_code TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'queued',summary_json TEXT NOT NULL,requested_by TEXT NOT NULL,taken_over_by TEXT,resumed_by TEXT,created_at INTEGER NOT NULL,taken_over_at INTEGER,resumed_at INTEGER);
CREATE TABLE IF NOT EXISTS ai_intent_versions (id TEXT PRIMARY KEY,intent_code TEXT NOT NULL,version INTEGER NOT NULL,status TEXT NOT NULL,business_owner TEXT NOT NULL,enabled INTEGER NOT NULL,confidence_threshold REAL NOT NULL,required_fields_json TEXT NOT NULL,workflow_mapping TEXT NOT NULL,escalation_rule TEXT NOT NULL,effective_from INTEGER,effective_to INTEGER,immutable_hash TEXT NOT NULL,created_by TEXT NOT NULL,reviewed_by TEXT,reviewed_at INTEGER,approved_by TEXT,approved_at INTEGER,activated_by TEXT,activated_at INTEGER,retired_at INTEGER,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,UNIQUE(intent_code,version));
CREATE TABLE IF NOT EXISTS ai_knowledge_source_versions (id TEXT PRIMARY KEY,source_key TEXT NOT NULL,version INTEGER NOT NULL,status TEXT NOT NULL,title TEXT NOT NULL,source_type TEXT NOT NULL,content_text TEXT NOT NULL,visibility_scope_json TEXT NOT NULL,effective_from INTEGER,effective_to INTEGER,immutable_hash TEXT NOT NULL,created_by TEXT NOT NULL,reviewed_by TEXT,reviewed_at INTEGER,approved_by TEXT,approved_at INTEGER,activated_by TEXT,activated_at INTEGER,retired_at INTEGER,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,UNIQUE(source_key,version));
CREATE TABLE IF NOT EXISTS ai_prompt_policy_versions (id TEXT PRIMARY KEY,policy_key TEXT NOT NULL,version INTEGER NOT NULL,status TEXT NOT NULL,system_prompt TEXT NOT NULL,policy_json TEXT NOT NULL,effective_from INTEGER,effective_to INTEGER,immutable_hash TEXT NOT NULL,created_by TEXT NOT NULL,reviewed_by TEXT,reviewed_at INTEGER,approved_by TEXT,approved_at INTEGER,activated_by TEXT,activated_at INTEGER,retired_at INTEGER,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,UNIQUE(policy_key,version));
