INSERT OR IGNORE INTO ai_assistant_profile_versions (id,profile_key,version,status,brand_voice,supported_languages_json,greeting_text,fallback_text,provider_ref,model_ref,effective_from,effective_to,immutable_hash,created_by,reviewed_by,reviewed_at,approved_by,approved_at,activated_by,activated_at,retired_at,created_at,updated_at) VALUES ('AIPROFILE-UATD0001-000','pawspace_default',1,'active','Warm, trustworthy, concise - a caring pet-care concierge.','["en","hi","ta"]','Hi! I''m the PawSpace assistant. How can I help you and your pet today?','I''m not fully sure about that - let me connect you to a PawSpace team member.','anthropic','claude-sonnet-4-6',NULL,NULL,'8e0c632507ca053fc8852755558e4dba6f9ba15d5730f2598f58de8be5838637','uat.demo.manager@tkpetcare.in','uat.demo.manager@tkpetcare.in',1786428000750,'founder@pawspace.in',1786428001250,'founder@pawspace.in',1786428001750,NULL,1786428000250,1786428001750);
INSERT OR IGNORE INTO ai_prompt_policy_versions (id,policy_key,version,status,system_prompt,policy_json,effective_from,effective_to,immutable_hash,created_by,reviewed_by,reviewed_at,approved_by,approved_at,activated_by,activated_at,retired_at,created_at,updated_at) VALUES ('AIPROMPT-UATD0006-000','pawspace_system',1,'active','You are the PawSpace assistant helping pet parents in India across WhatsApp, chat and voice.
Rules you must always follow:
- Only answer from the approved PawSpace knowledge and the server tools. If you don''t know, say so and offer a human.
- Never quote a price, discount or availability from memory - always use the live quote/catalogue tool.
- Never claim an action is done (booking, payment, refund, cancellation) unless a tool confirms it.
- You cannot issue refunds, capture payments, change prices, assign providers or start campaigns - hand those to a human.
- Immediately hand off complaints, refund/payment disputes, safety and any pet medical emergency to a human. Never give medical advice.
- Be warm, concise and clear. Reply in the customer''s language (English, Hindi or Tamil) when you can.','{"groundedOnly":true,"neverQuotePriceFromMemory":true,"forbiddenAutonomousActions":["refund","payment","price_change","provider_assignment","campaign_activation"],"handoffTopics":["complaint","refund_dispute","payment_dispute","safety","medical_emergency"]}',NULL,NULL,'cbcb714fd80194624dfd6e97dd87c04ff7aad1c1a9b6de947bdb807b6ec041cd','uat.demo.manager@tkpetcare.in','uat.demo.manager@tkpetcare.in',1786428002750,'founder@pawspace.in',1786428003250,'founder@pawspace.in',1786428003750,NULL,1786428002250,1786428003750);
INSERT OR IGNORE INTO ai_knowledge_source_versions (id,source_key,version,status,title,source_type,content_text,visibility_scope_json,effective_from,effective_to,immutable_hash,created_by,reviewed_by,reviewed_at,approved_by,approved_at,activated_by,activated_at,retired_at,created_at,updated_at) VALUES ('AIKNOW-UATD0011-000','services_overview',1,'active','PawSpace services','policy','PawSpace offers at-home and doorstep pet care: Grooming, Dog Training, Boarding, Pet Sitting, Pet Taxi (pick & drop), Dog Walking, Fresh Food, and Funeral/Memorial. Bookings are made in the app; a vetted provider is auto-assigned. Prices are always quoted live from the current catalogue - never quote a price from memory; use the quote tool.','["public"]',NULL,NULL,'69c95c60a3e91a90121f2a7d5fc24a75879d3418981a49809aa78eda75e3dc1d','uat.demo.manager@tkpetcare.in','uat.demo.manager@tkpetcare.in',1786428004750,'founder@pawspace.in',1786428005250,'founder@pawspace.in',1786428005750,NULL,1786428004250,1786428005750);
INSERT OR IGNORE INTO ai_knowledge_source_versions (id,source_key,version,status,title,source_type,content_text,visibility_scope_json,effective_from,effective_to,immutable_hash,created_by,reviewed_by,reviewed_at,approved_by,approved_at,activated_by,activated_at,retired_at,created_at,updated_at) VALUES ('AIKNOW-UATD0016-000','how_booking_works',1,'active','How booking works','policy','The customer picks a service, pet, date and time; PawSpace auto-schedules a governed provider and confirms the booking. For online payment the customer pays via UPI/GPay through a secure Razorpay order and the booking is marked paid only after the payment is verified. Booking status, reschedules and cancellations are available in the app.','["public"]',NULL,NULL,'1ffd4bd1db26230aa9e219bb8bd935a5827374f8ada3912e75ddd6d6a925f6d8','uat.demo.manager@tkpetcare.in','uat.demo.manager@tkpetcare.in',1786428006750,'founder@pawspace.in',1786428007250,'founder@pawspace.in',1786428007750,NULL,1786428006250,1786428007750);
INSERT OR IGNORE INTO ai_knowledge_source_versions (id,source_key,version,status,title,source_type,content_text,visibility_scope_json,effective_from,effective_to,immutable_hash,created_by,reviewed_by,reviewed_at,approved_by,approved_at,activated_by,activated_at,retired_at,created_at,updated_at) VALUES ('AIKNOW-UATD0021-000','cancellation_refund',1,'active','Cancellations & refunds','policy','A customer can cancel or reschedule from the app subject to the service''s policy. Eligible refunds are governed and reviewed by Finance (maker/checker) before any money moves; the assistant never promises or issues a refund itself - it hands off refund and payment-dispute requests to a human.','["public"]',NULL,NULL,'883c5c1b18ed3b3be1d984eee77a44270a962b4d2122cf7cc7d8575f3a540318','uat.demo.manager@tkpetcare.in','uat.demo.manager@tkpetcare.in',1786428008750,'founder@pawspace.in',1786428009250,'founder@pawspace.in',1786428009750,NULL,1786428008250,1786428009750);
INSERT OR IGNORE INTO ai_knowledge_source_versions (id,source_key,version,status,title,source_type,content_text,visibility_scope_json,effective_from,effective_to,immutable_hash,created_by,reviewed_by,reviewed_at,approved_by,approved_at,activated_by,activated_at,retired_at,created_at,updated_at) VALUES ('AIKNOW-UATD0026-000','pawspace_wallet',1,'active','PawSpace Wallet','policy','PawSpace Wallet holds store credit that can come from a refund, a cancellation, or goodwill. When wallet credit is spent on a future booking the customer gets 10% enhanced value - every Rs.100 of wallet becomes Rs.110 of booking value, never applied beyond the booking total. The wallet balance and history are visible in the app.','["public"]',NULL,NULL,'826c68106668f15d52b2854b12989e472ab75615bdcc90a472d26d316d680a2f','uat.demo.manager@tkpetcare.in','uat.demo.manager@tkpetcare.in',1786428010750,'founder@pawspace.in',1786428011250,'founder@pawspace.in',1786428011750,NULL,1786428010250,1786428011750);
INSERT OR IGNORE INTO ai_knowledge_source_versions (id,source_key,version,status,title,source_type,content_text,visibility_scope_json,effective_from,effective_to,immutable_hash,created_by,reviewed_by,reviewed_at,approved_by,approved_at,activated_by,activated_at,retired_at,created_at,updated_at) VALUES ('AIKNOW-UATD0031-000','paw_points_loyalty',1,'active','PawPoints loyalty','policy','Customers earn PawPoints on completed bookings and can redeem them for a discount on a future booking (redemption is capped per booking). Goodwill and win-back points may also be granted by staff. Balances and the full points ledger are shown in the app.','["public"]',NULL,NULL,'9126b8ea206ce588eb5ce8715292ca8b313c79816d67fdae13493e8afc5b0403','uat.demo.manager@tkpetcare.in','uat.demo.manager@tkpetcare.in',1786428012750,'founder@pawspace.in',1786428013250,'founder@pawspace.in',1786428013750,NULL,1786428012250,1786428013750);
INSERT OR IGNORE INTO ai_knowledge_source_versions (id,source_key,version,status,title,source_type,content_text,visibility_scope_json,effective_from,effective_to,immutable_hash,created_by,reviewed_by,reviewed_at,approved_by,approved_at,activated_by,activated_at,retired_at,created_at,updated_at) VALUES ('AIKNOW-UATD0036-000','pet_passport',1,'active','Pet Passport','policy','The Pet Passport is one shareable card per pet that ties together the pet''s basics, birthday, real vaccination status and the owner''s loyalty tier, with badges like ''Fully Vaccinated''. Owners can share a privacy-safe public link that shows the pet''s card with no owner personal details.','["public"]',NULL,NULL,'f535aa85044a71e5368e1fff39c912666b4cf3332da578cf1752d49ef185e66f','uat.demo.manager@tkpetcare.in','uat.demo.manager@tkpetcare.in',1786428014750,'founder@pawspace.in',1786428015250,'founder@pawspace.in',1786428015750,NULL,1786428014250,1786428015750);
INSERT OR IGNORE INTO ai_knowledge_source_versions (id,source_key,version,status,title,source_type,content_text,visibility_scope_json,effective_from,effective_to,immutable_hash,created_by,reviewed_by,reviewed_at,approved_by,approved_at,activated_by,activated_at,retired_at,created_at,updated_at) VALUES ('AIKNOW-UATD0041-000','vaccination_reminders',1,'active','Vaccination records & reminders','policy','PawSpace stores each pet''s vaccination records and due dates and reminds the owner when a vaccination is due or overdue. Keeping vaccinations up to date is required for some services like Boarding.','["public"]',NULL,NULL,'871d1a7823bea25ac8d34406ec8023ef87c5f5b045c08f2d1680cfea6d2383b0','uat.demo.manager@tkpetcare.in','uat.demo.manager@tkpetcare.in',1786428016750,'founder@pawspace.in',1786428017250,'founder@pawspace.in',1786428017750,NULL,1786428016250,1786428017750);
INSERT OR IGNORE INTO ai_knowledge_source_versions (id,source_key,version,status,title,source_type,content_text,visibility_scope_json,effective_from,effective_to,immutable_hash,created_by,reviewed_by,reviewed_at,approved_by,approved_at,activated_by,activated_at,retired_at,created_at,updated_at) VALUES ('AIKNOW-UATD0046-000','birthday_offer',1,'active','Pet birthday offer','policy','Around a pet''s birthday, PawSpace surfaces a birthday grooming offer for that pet. The assistant can mention an upcoming birthday and the offer, but the exact discount is applied by the app, not quoted from memory.','["public"]',NULL,NULL,'cbabd8fc1d738a0bd5b7aea451210a10725ca4ff85d09ed19872ca0ec48bc15e','uat.demo.manager@tkpetcare.in','uat.demo.manager@tkpetcare.in',1786428018750,'founder@pawspace.in',1786428019250,'founder@pawspace.in',1786428019750,NULL,1786428018250,1786428019750);
INSERT OR IGNORE INTO ai_knowledge_source_versions (id,source_key,version,status,title,source_type,content_text,visibility_scope_json,effective_from,effective_to,immutable_hash,created_by,reviewed_by,reviewed_at,approved_by,approved_at,activated_by,activated_at,retired_at,created_at,updated_at) VALUES ('AIKNOW-UATD0051-000','reviews_rewards',1,'active','Reviews & rewards','policy','After a service the customer may be asked to review it. A 5-star rating surfaces the Google and app review links. Posting a public review can earn a coupon (one review earns a coupon; both platforms on the same order earn a larger grooming coupon), subject to the reward terms.','["public"]',NULL,NULL,'a74c386a273f8bda647c22b931d601656c5147821adbd7e2f0765fef45d15d5a','uat.demo.manager@tkpetcare.in','uat.demo.manager@tkpetcare.in',1786428020750,'founder@pawspace.in',1786428021250,'founder@pawspace.in',1786428021750,NULL,1786428020250,1786428021750);
INSERT OR IGNORE INTO ai_knowledge_source_versions (id,source_key,version,status,title,source_type,content_text,visibility_scope_json,effective_from,effective_to,immutable_hash,created_by,reviewed_by,reviewed_at,approved_by,approved_at,activated_by,activated_at,retired_at,created_at,updated_at) VALUES ('AIKNOW-UATD0056-000','emergency_help',1,'active','Emergency help','policy','The app has an emergency help option for urgent pet situations that raises a priority case and can dispatch help. For any medical emergency, advise contacting a veterinarian immediately - the assistant never gives a medical diagnosis and always escalates safety and emergency matters to a human.','["public"]',NULL,NULL,'bb8a1e9bdb555af549b4e9f991139abf67aa0eb4033d15b7e0ebcc4eba8b2269','uat.demo.manager@tkpetcare.in','uat.demo.manager@tkpetcare.in',1786428022750,'founder@pawspace.in',1786428023250,'founder@pawspace.in',1786428023750,NULL,1786428022250,1786428023750);
